var createTheme = ({ theme: theme4, settings: settings41, styles }) => {
  const _theme = EditorView.theme(
    {
      "&": {
        color: settings41.foreground,
        backgroundColor: settings41.background
      },
      ".cm-gutters": {
        backgroundColor: settings41.gutterBackground,
        color: settings41.gutterForeground
        //borderRightColor: settings.gutterBorder
      },
      ".cm-content": {
        caretColor: settings41.caret
      },
      ".cm-cursor, .cm-dropCursor": {
        borderLeftColor: settings41.caret
      },
      ".cm-activeLineGutter": {
        // color: settings.gutterActiveForeground
        backgroundColor: settings41.lineHighlight
      },
      ".cm-activeLine": {
        backgroundColor: settings41.lineHighlight
      },
      "&.cm-focused .cm-selectionBackground, & .cm-line::selection, & .cm-selectionLayer .cm-selectionBackground, .cm-content ::selection": {
        background: settings41.selection + " !important"
      },
      "& .cm-selectionMatch": {
        backgroundColor: settings41.selectionMatch
      }
    },
    { dark: theme4 === "dark" }
  );
  const highlightStyle = HighlightStyle.define(styles);
  return [_theme, syntaxHighlighting(highlightStyle)];
};

